import { Routes, Route, Navigate } from 'react-router-dom';
import { useState } from 'react';

import Header from './components/Header/Header';
import Footer from './components/Footer/Footer';

import CatalogPage from './pages/CatalogPage/CatalogPage';
import FavoritesPage from './pages/FavoritesPage/FavoritesPage';
import ExcursionPage from './pages/ExcursionPage/ExcursionPage';
import CartPage from './pages/CartPage/CartPage';
import LoginPage from './pages/LoginPage/LoginPage';
import RegisterPage from './pages/RegisterPage/RegisterPage';
import ProfilePage from './pages/ProfilePage/UserProfile'

function App() {
  const [favoriteIds, setFavoriteIds] = useState([]);

  const toggleFavorite = (id) => {
    setFavoriteIds((prev) =>
      prev.includes(id)
        ? prev.filter((item) => item !== id)
        : [...prev, id]
    );
  };

  return (
    <div className="App">
      <Header />
      <main className="main-content">
        <Routes>
          <Route path="/" element={<Navigate to="/catalog" />} />
          <Route path="/catalog" element={<CatalogPage favoriteIds={favoriteIds} onToggleFavorite={toggleFavorite}/>}/>
          <Route path="/favorites" element={<FavoritesPage favoriteIds={favoriteIds} onToggleFavorite={toggleFavorite}/>}/>
          <Route path="/tour/:id" element={<ExcursionPage favoriteIds={favoriteIds} onToggleFavorite={toggleFavorite}/>}/>
          <Route path="/cart" element={<CartPage />}/>
          <Route path="/login" element={<LoginPage />}/>
          <Route path="/profile" element={<ProfilePage />}/>
          <Route path="/register" element={<RegisterPage />}/>
        </Routes>
      </main>

      <Footer />
    </div>
  );
}

export default App;
